const targets = $input.all().map(item => item.json);

if (targets.length === 0) {
  throw new Error('No active PTS collection targets were returned');
}

const required = ['organization_id', 'account_id', 'brand_id', 'studio_id', 'studio_code', 'studio_name', 'timezone', 'pts_location_id'];
const grouped = new Map();
const seenStudios = new Set();

for (const target of targets) {
  const missing = required.filter(field => target[field] === null || target[field] === undefined || String(target[field]).trim() === '');
  if (missing.length) {
    throw new Error(`Incomplete PTS collection target for studio ${target.studio_id ?? 'unknown'}: ${missing.join(', ')}`);
  }

  const accountId = Number(target.account_id);
  const organizationId = Number(target.organization_id);
  const brandId = Number(target.brand_id);
  const studioId = Number(target.studio_id);
  if (![accountId, organizationId, brandId, studioId].every(Number.isSafeInteger)) {
    throw new Error(`Invalid numeric PTS target identifiers for studio ${target.studio_id}`);
  }

  const studioKey = `${organizationId}:${studioId}`;
  if (seenStudios.has(studioKey)) {
    throw new Error(`Studio ${studioId} is mapped to more than one active PTS account`);
  }
  seenStudios.add(studioKey);

  const existing = grouped.get(accountId);
  if (existing && existing.organizationId !== organizationId) {
    throw new Error(`PTS account ${accountId} crosses organization boundaries`);
  }

  const job = existing ?? {
    dispatcherVersion: 1,
    organizationId,
    accountId,
    studioTargets: []
  };

  job.studioTargets.push({
    studioId,
    brandId,
    studioCode: String(target.studio_code),
    studioName: String(target.studio_name),
    timezone: String(target.timezone),
    ptsLocationId: String(target.pts_location_id),
    reports: target.reports && typeof target.reports === 'object' ? target.reports : {}
  });
  grouped.set(accountId, job);
}

return [...grouped.values()]
  .sort((a, b) => a.accountId - b.accountId)
  .map(job => ({
    json: {
      ...job,
      studioTargets: job.studioTargets.sort((a, b) => a.studioId - b.studioId),
      studioCount: job.studioTargets.length
    }
  }));
